-- SPENCE schema: a fresh database after every migration in core/db_helper.php.
-- Generated by ops/rebuild-schema.php; edit the migrations, not this file.
CREATE TABLE products (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, category TEXT NOT NULL, kj_per_100 REAL DEFAULT 0, protein_per_100 REAL DEFAULT 0, fat_per_100 REAL DEFAULT 0, carb_per_100 REAL DEFAULT 0, weight_per_ea REAL DEFAULT 1.0, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, merges_into INTEGER REFERENCES products(id), last_unit_cost REAL DEFAULT 0, recipe_id INTEGER REFERENCES recipes(id), type TEXT DEFAULT 'raw' CHECK(type IN ('raw', 'cooked')), base_unit TEXT DEFAULT 'kg', is_dropped BOOLEAN DEFAULT 0);
CREATE TABLE inventory (id INTEGER PRIMARY KEY AUTOINCREMENT, product_id INTEGER NOT NULL, current_qty REAL NOT NULL, unit TEXT NOT NULL, price_paid REAL DEFAULT 0, location TEXT DEFAULT 'Pantry', expiry_date DATE, expiry_source TEXT, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (product_id) REFERENCES products(id));
CREATE TABLE recipes (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, instructions TEXT, yield_serves INTEGER DEFAULT 1, product_id INTEGER REFERENCES products(id), is_active INTEGER DEFAULT 1, parent_recipe_id INTEGER REFERENCES recipes(id), version INTEGER DEFAULT 1, tags TEXT);
CREATE TABLE recipe_ingredients (id INTEGER PRIMARY KEY AUTOINCREMENT, recipe_id INTEGER NOT NULL, product_id INTEGER NOT NULL, amount REAL NOT NULL, unit TEXT NOT NULL, wastage_factor REAL DEFAULT 1.0, FOREIGN KEY (recipe_id) REFERENCES recipes(id), FOREIGN KEY (product_id) REFERENCES products(id));
CREATE TABLE consumption_log (id INTEGER PRIMARY KEY AUTOINCREMENT, product_id INTEGER, recipe_id INTEGER, amount REAL, unit TEXT, kj REAL, protein REAL, fat REAL, carb REAL, consumed_at DATETIME DEFAULT CURRENT_TIMESTAMP, unit_cost REAL DEFAULT 0, source TEXT DEFAULT 'inventory', name TEXT, quick_eat_kj_per_100 REAL, quick_eat_protein_per_100 REAL, quick_eat_fat_per_100 REAL, quick_eat_carb_per_100 REAL, quick_eat_weight_per_ea REAL);
CREATE TABLE jobs (id INTEGER PRIMARY KEY AUTOINCREMENT, file_path TEXT, status TEXT DEFAULT 'pending', message TEXT, result_json TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE product_aliases (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    raw_name TEXT NOT NULL UNIQUE,
    canonical_product_id INTEGER NOT NULL REFERENCES products(id),
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE user_profiles (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    dob DATE,
    gender TEXT,
    height_cm REAL,
    activity_rate REAL, -- multiplier e.g. 1.2 to 1.9
    weekly_budget REAL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
, activity_rate_override INTEGER NOT NULL DEFAULT 0);
CREATE TABLE user_vitals_history (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL REFERENCES user_profiles(id),
    weight_kg REAL NOT NULL,
    body_fat_pct REAL,
    recorded_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE user_goals_history (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL REFERENCES user_profiles(id),
    goal_type TEXT, -- weight loss, muscle gain, maintenance
    target_kj REAL,
    target_protein_g REAL,
    target_fat_g REAL,
    target_carb_g REAL,
    cost_limit_daily REAL,
    regime TEXT,
    maintenance_kj REAL,
    goal_adjustment_kj REAL,
    training_adjustment_kj REAL,
    maintenance_source TEXT,
    start_date DATE DEFAULT CURRENT_DATE,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE recipe_tags_master (tag_name TEXT PRIMARY KEY);
CREATE TABLE dedupe_dismissed (id INTEGER PRIMARY KEY AUTOINCREMENT, product_id_a INTEGER NOT NULL, product_id_b INTEGER NOT NULL, dismissed_at DATETIME DEFAULT CURRENT_TIMESTAMP, UNIQUE(product_id_a, product_id_b));
CREATE TABLE schema_migrations (
        version TEXT PRIMARY KEY,
        applied_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE spice_rack (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT NOT NULL UNIQUE COLLATE NOCASE,
        is_stocked INTEGER NOT NULL DEFAULT 1,
        uses_since_restock INTEGER NOT NULL DEFAULT 0,
        restock_flagged INTEGER NOT NULL DEFAULT 0,
        last_restocked_at DATETIME DEFAULT CURRENT_TIMESTAMP,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE recipe_spices (
        recipe_id INTEGER NOT NULL,
        spice_id INTEGER NOT NULL,
        PRIMARY KEY (recipe_id, spice_id),
        FOREIGN KEY (recipe_id) REFERENCES recipes(id) ON DELETE CASCADE,
        FOREIGN KEY (spice_id) REFERENCES spice_rack(id) ON DELETE CASCADE
        );
CREATE TABLE energy_day_exclusions (
            day DATE PRIMARY KEY,
            excluded_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE energy_preferences (
            id INTEGER PRIMARY KEY CHECK (id = 1),
            use_calibrated_targets INTEGER NOT NULL DEFAULT 0,
            goal_adjustment_kj REAL NOT NULL DEFAULT 0,
            training_adjustment_kj REAL NOT NULL DEFAULT 0,
            updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE spice_aliases (
            raw_name TEXT PRIMARY KEY COLLATE NOCASE,
            spice_id INTEGER NOT NULL,
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (spice_id) REFERENCES spice_rack(id) ON DELETE CASCADE
        );
CREATE TABLE purchase_log (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            product_id INTEGER,
            qty REAL NOT NULL,
            unit TEXT,
            price REAL NOT NULL DEFAULT 0,
            source TEXT NOT NULL,
            job_id INTEGER,
            purchased_at DATETIME DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE waste_log (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            product_id INTEGER,
            qty REAL NOT NULL,
            unit TEXT,
            value REAL NOT NULL DEFAULT 0,
            wasted_at DATETIME DEFAULT CURRENT_TIMESTAMP
        );
CREATE INDEX idx_consumption_log_consumed_at ON consumption_log(consumed_at);
CREATE INDEX idx_consumption_log_product_id ON consumption_log(product_id);
CREATE INDEX idx_inventory_product_location ON inventory(product_id, location);
CREATE INDEX idx_inventory_product_quantity ON inventory(product_id, current_qty);
CREATE INDEX idx_recipe_ingredients_recipe_id ON recipe_ingredients(recipe_id);
CREATE INDEX idx_recipe_ingredients_product_id ON recipe_ingredients(product_id);
CREATE INDEX idx_user_vitals_recorded_at ON user_vitals_history(recorded_at);
CREATE INDEX idx_inventory_expiry_date ON inventory(expiry_date) WHERE expiry_date IS NOT NULL;
CREATE INDEX idx_energy_day_exclusions_day ON energy_day_exclusions(day);
CREATE INDEX idx_user_goals_effective_date ON user_goals_history(user_id, start_date, created_at);
CREATE INDEX idx_purchase_log_purchased_at ON purchase_log(purchased_at);
CREATE INDEX idx_waste_log_wasted_at ON waste_log(wasted_at);
